(() => {
  "use strict";

  const $ = s => document.querySelector(s);
  const el = (tag, cls, text) => { const e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; };
  const PAGE = 48;   // cards shown at once; "Zobrazit další" adds more

  // Games come either from RAWG (data/games.js generated by tools/) or the older hand-made Steam list.
  const isRawg = g => "img" in g;
  const cover = g => isRawg(g)
    ? (g.img ? g.img.replace("/media/", "/media/resize/640/-/") : "")          // RAWG serves resized images under /media/resize/
    : `https://shared.cloudflare.steamstatic.com/store_item_assets/steam/apps/${g.id}/header.jpg`;
  const link = g => isRawg(g) ? `https://rawg.io/games/${g.slug}` : `https://store.steampowered.com/app/${g.id}/`;
  const metaText = g => [g.year, isRawg(g) ? (g.genres || []).join(", ") : g.dev].filter(Boolean).join(" · ");

  // Matching key for typed names: ignores case, spaces, dashes and brand words,
  // so "Intel Core i5-4460", "i5 4460" and "core i5-4460" all mean the same part.
  const norm = s => String(s || "").toLowerCase()
    .replace(/\b(intel|amd|nvidia|geforce|radeon|core|procesor|grafika|graphics)\b/g, "")
    .replace(/[\s\-_.()®™]/g, "");

  // ---------- Component lookup ----------
  const byName = { cpu: new Map(), gpu: new Map() };
  for (const p of globalThis.CPUS) byName.cpu.set(p.name, p);
  for (const p of globalThis.GPUS) byName.gpu.set(p.name, p);
  // fuzzy lookup for what the user types ("rtx3060", "ryzen 5 3600", "780m", …)
  const byNorm = { cpu: new Map(), gpu: new Map() };
  for (const [kind, parts] of [["cpu", globalThis.CPUS], ["gpu", globalThis.GPUS]]) {
    const m = byNorm[kind];
    for (const p of parts.filter(p => !p.hidden)) {
      m.set(norm(p.name), p);
      const short = norm(p.name.replace(/\s*\(.*\)\s*/, ""));     // "Radeon 780M (integrovaná)" → also "780m"
      if (short && !m.has(short)) m.set(short, p);
    }
    for (const [alias, name] of Object.entries((globalThis.PART_ALIASES || {})[kind] || {})) {
      const p = byName[kind].get(name);
      if (p && !m.has(norm(alias))) m.set(norm(alias), p);
    }
  }

  // Requirement threshold = the weakest of the listed alternatives (any one of them is enough).
  function threshold(kind, names) {
    if (!names) return null;
    const scores = names.map(n => {
      const p = byName[kind].get(n);
      if (!p) console.warn(`Neznámá komponenta v požadavcích: ${kind} "${n}"`);
      return p ? p.score : null;
    }).filter(s => s != null);
    return scores.length ? Math.min(...scores) : null;
  }
  const GAMES = (globalThis.GAMES || []).map(g => ({
    ...g,
    t: {
      min: { cpu: threshold("cpu", g.min.cpu), gpu: threshold("gpu", g.min.gpu), ram: g.min.ram },
      rec: g.rec ? { cpu: threshold("cpu", g.rec.cpu), gpu: threshold("gpu", g.rec.gpu), ram: g.rec.ram } : null
    }
  }));
  const released = GAMES.filter(g => !g.upcoming);
  const upcoming = GAMES.filter(g => g.upcoming);
  // how demanding a game is (for sorting): its recommended GPU, or minimum if there's none
  const weight = g => (g.t.rec && g.t.rec.gpu != null ? g.t.rec.gpu : g.t.min.gpu) || 0;

  // ---------- Build (the user's PC) ----------
  const build = { cpu: null, gpu: null, ram: null };
  const fillList = (list, parts) => parts.filter(p => !p.hidden).forEach(p => { const o = document.createElement("option"); o.value = p.name; list.append(o); });
  fillList($("#cpuList"), globalThis.CPUS);
  fillList($("#gpuList"), globalThis.GPUS);

  function readPart(kind) {
    const input = $("#" + kind), msg = $("#" + kind + "Msg");
    const v = input.value.trim();
    const p = byNorm[kind].get(norm(v)) || null;
    build[kind] = p;
    msg.className = "field-msg" + (v && !p ? " bad" : p ? " good" : "");
    msg.textContent = !v ? "" : p ? `Orientační výkon: ${p.score}` : "Tuhle komponentu zatím neznám – vyber ji z nabídky.";
  }
  ["cpu", "gpu"].forEach(k => {
    $("#" + k).addEventListener("input", () => { readPart(k); save(); render(true); });
    // when leaving the box, tidy what was typed ("rtx3060") into the exact name ("RTX 3060")
    $("#" + k).addEventListener("change", () => { if (build[k]) { $("#" + k).value = build[k].name; save(); } });
  });
  $("#ram").addEventListener("change", e => { build.ram = Number(e.target.value) || null; save(); render(true); });

  // remember the build in this browser (a convenience only – works without it)
  function save() {
    try { localStorage.setItem("rozjede-build", JSON.stringify({ cpu: $("#cpu").value, gpu: $("#gpu").value, ram: $("#ram").value })); } catch (e) {}
  }
  try {
    const s = JSON.parse(localStorage.getItem("rozjede-build") || "null");
    if (s) { $("#cpu").value = s.cpu || ""; $("#gpu").value = s.gpu || ""; $("#ram").value = s.ram || ""; build.ram = Number(s.ram) || null; readPart("cpu"); readPart("gpu"); }
  } catch (e) {}
  const complete = () => build.cpu && build.gpu && build.ram;

  // ---------- Verdict ----------
  // The scores are estimates, so a part within 5 % of the requirement counts as meeting it
  // (e.g. Ryzen 5 3600 vs. a recommended 3600X). RAM is compared exactly.
  const TOLERANCE = 0.95;
  function level(mine, min, rec, exact) {
    const meets = need => mine >= (exact ? need : need * TOLERANCE);
    if (min == null) return "great";             // no requirement given
    if (rec != null && meets(rec)) return "great";
    if (meets(min)) return rec == null ? "great" : "ok";
    return "no";
  }
  const RANK = { great: 0, ok: 1, no: 2 };
  // Some RAWG games have requirements we couldn't (fully) read. Those still show up:
  //   no CPU and no GPU recognised → "unknown"; only one of them → verdict from what we know, marked partial.
  const knownReq = g => g.t.min.cpu != null || g.t.min.gpu != null;
  function verdict(g) {
    if (!complete()) return null;
    if (!knownReq(g)) return { overall: "unknown", parts: {}, partial: false };
    const mine = { cpu: build.cpu.score, gpu: build.gpu.score, ram: build.ram };
    const parts = {};
    for (const k of ["cpu", "gpu", "ram"]) {
      parts[k] = g.t.min[k] == null ? "unknown" : level(mine[k], g.t.min[k], g.t.rec ? g.t.rec[k] : null, k === "ram");
    }
    const overall = Object.values(parts).filter(p => p !== "unknown").reduce((a, b) => RANK[b] > RANK[a] ? b : a, "great");
    return { overall, parts, mine, partial: parts.cpu === "unknown" || parts.gpu === "unknown" };
  }
  const LABEL = { great: "Rozjedeš", ok: "Na nízké detaily", no: "Nerozjedeš" };
  const SUB = { great: "splňuješ doporučené požadavky", ok: "splňuješ jen minimum", no: "nesplňuješ minimum" };
  const unknownLabel = g => g.noReq ? "Požadavky neznámé" : "Požadavky nerozpoznány";
  // "Asi rozjedeš" when part of the requirements couldn't be read (a failing known part is still a clear "no")
  const label = v => v.partial && v.overall !== "no" ? { great: "Asi rozjedeš", ok: "Asi na nízké detaily" }[v.overall] : LABEL[v.overall];

  // ---------- Views: all games / release calendar ----------
  // default sort: by popularity when the data has it (RAWG runs from now on), otherwise by name
  const hasPop = GAMES.some(g => g.pop);
  if (!hasPop) $('#sort option[value="pop"]').remove();
  const state = { view: "all", q: "", v: "all", sort: hasPop ? "pop" : "new", shown: PAGE };
  $("#sort").value = state.sort;
  $("#search").addEventListener("input", e => { state.q = norm(e.target.value); render(true); });
  $("#sort").addEventListener("change", e => { state.sort = e.target.value; render(true); });
  document.querySelectorAll("#verdictFilter button").forEach(b => b.addEventListener("click", () => {
    state.v = b.dataset.v;
    document.querySelectorAll("#verdictFilter button").forEach(x => x.setAttribute("aria-pressed", x === b));
    render(true);
  }));
  function setView(v) {
    state.view = v;
    $("#tabAll").setAttribute("aria-selected", v === "all");
    $("#tabCal").setAttribute("aria-selected", v === "cal");
    $("#sort").hidden = v === "cal";                         // the calendar is always by release date
    render(true);
  }
  $("#tabAll").addEventListener("click", () => setView("all"));
  $("#tabCal").addEventListener("click", () => setView("cal"));
  $("#moreBtn").addEventListener("click", () => { state.shown += PAGE; render(false); });
  $("#countAll").textContent = released.length;
  $("#countCal").textContent = upcoming.length;
  if (!upcoming.length) $("#tabCal").hidden = true;

  const hashStr = s => { let h = 0; for (const ch of String(s)) h = (h * 31 + ch.charCodeAt(0)) | 0; return Math.abs(h); };
  const MONTHS = ["leden", "únor", "březen", "duben", "květen", "červen", "červenec", "srpen", "září", "říjen", "listopad", "prosinec"];
  const fmtDate = d => { const x = new Date(d + "T00:00:00"); return isNaN(x) ? "" : `${x.getDate()}. ${x.getMonth() + 1}. ${x.getFullYear()}`; };

  function card(g, v) {
    const c = el("button", "card"); c.type = "button";
    // picture, or a coloured placeholder with the first letter when there's none (or it fails to load)
    const placeholder = () => { const ph = el("div", "ph", (g.name || "?").trim().charAt(0).toUpperCase()); ph.style.setProperty("--h", (hashStr(g.name) % 360) + "deg"); ph.setAttribute("aria-hidden", "true"); return ph; };
    let pic;
    const src = cover(g);
    if (src) {
      pic = el("img"); pic.alt = ""; pic.loading = "lazy"; pic.src = src;
      pic.onerror = () => {
        if (isRawg(g) && g.img && pic.src !== g.img) { pic.src = g.img; return; }   // try the full-size original once
        pic.replaceWith(placeholder());
      };
    } else pic = placeholder();
    const body = el("div", "card-body");
    const h = el("h3", null, g.name);
    if (g.free) h.append(el("span", "free", "ZDARMA"));
    body.append(h, el("div", "meta", g.upcoming ? (g.tba || !g.released ? "Datum zatím neznámé" : "Vychází " + fmtDate(g.released)) : metaText(g)));
    if (!knownReq(g)) body.append(el("span", "badge none", unknownLabel(g)));
    else body.append(v ? el("span", "badge " + v.overall + (v.partial ? " partial" : ""), label(v)) : el("span", "badge none", "Zadej sestavu"));
    c.append(pic, body);
    c.addEventListener("click", () => openDetail(g));
    return c;
  }

  function render(resetPaging) {
    if (resetPaging) state.shown = PAGE;
    const pool = state.view === "cal" ? upcoming : released;
    const results = pool.map(g => ({ g, v: verdict(g) }));

    // summary under the build (always about released games)
    const sum = $("#summary"); sum.textContent = "";
    if (complete()) {
      const all = released.map(verdict);
      const c = k => all.filter(v => v.overall === k).length;
      const judged = all.length - c("unknown");
      sum.append("Z ", el("strong", null, `${judged} her`), " rozjedeš ",
        el("strong", "g", `${c("great")} na doporučené`), ", ", el("strong", "o", `${c("ok")} jen na minimum`), " a ", el("strong", "n", `${c("no")} vůbec`), ".");
      if (c("unknown")) sum.append(` U dalších ${c("unknown")} her požadavky neznáme nebo je neumíme přečíst.`);
    } else sum.textContent = "Vyplň všechna tři políčka a u každé hry uvidíš, jestli ji rozjedeš.";

    const byRelease = (a, b) => (a.g.tba || !a.g.released) - (b.g.tba || !b.g.released) || String(a.g.released).localeCompare(String(b.g.released)) || a.g.name.localeCompare(b.g.name, "cs");
    const sorters = {
      pop: (a, b) => (a.g.pop || 1e9) - (b.g.pop || 1e9),
      name: (a, b) => a.g.name.localeCompare(b.g.name, "cs"),
      new: (a, b) => String(b.g.released || b.g.year).localeCompare(String(a.g.released || a.g.year)) || a.g.name.localeCompare(b.g.name, "cs"),
      heavy: (a, b) => weight(b.g) - weight(a.g),
      light: (a, b) => weight(a.g) - weight(b.g)
    };
    const list = results
      .filter(r => !state.q || norm(r.g.name).includes(state.q) || norm(metaText(r.g)).includes(state.q))
      .filter(r => state.v === "all" || (r.v && r.v.overall === state.v))
      .sort(state.view === "cal" ? byRelease : sorters[state.sort]);

    $("#listNote").textContent = state.view === "cal"
      ? "PC hry, které teprve vyjdou a už mají zveřejněné požadavky. Další přibudou s každou aktualizací."
      : `${list.length === pool.length ? pool.length : list.length + " z " + pool.length} her`;

    const grid = $("#grid"); grid.textContent = "";
    if (!list.length) {
      grid.append(el("div", "empty", state.v !== "all" && !complete() ? "Nejdřív vyplň svou sestavu nahoře." : "Žádná hra neodpovídá hledání."));
      $("#moreBtn").hidden = true;
      return;
    }
    let lastMonth = null;
    for (const { g, v } of list.slice(0, state.shown)) {
      if (state.view === "cal") {
        const key = g.tba || !g.released ? "tba" : g.released.slice(0, 7);
        if (key !== lastMonth) {
          lastMonth = key;
          const [y, m] = key.split("-");
          grid.append(el("h3", "month", key === "tba" ? "Datum zatím neznámé" : `${MONTHS[+m - 1]} ${y}`));
        }
      }
      grid.append(card(g, v));
    }
    const rest = list.length - state.shown;
    $("#moreBtn").hidden = rest <= 0;
    $("#moreBtn").textContent = `Zobrazit další (${Math.min(PAGE, rest)} z ${rest})`;
  }

  // ---------- Detail window ----------
  const dlg = $("#detail");
  dlg.addEventListener("click", e => { if (e.target === dlg) dlg.close(); });
  document.querySelectorAll("[data-close]").forEach(b => b.addEventListener("click", () => b.closest("dialog").close()));
  const KIND = { cpu: "Procesor", gpu: "Grafika", ram: "Paměť" };
  const gb = n => String(n).replace(".", ",") + " GB";

  function openDetail(g) {
    const v = verdict(g);
    const img = $("#dImg"); const src = cover(g);
    img.hidden = !src; if (src) img.src = src;
    img.onerror = () => { img.hidden = true; };
    $("#dTitle").textContent = g.name;
    $("#dMeta").textContent = [g.upcoming ? (g.tba || !g.released ? "datum vydání zatím neznámé" : "vychází " + fmtDate(g.released)) : null, metaText(g), g.free ? "zdarma" : null].filter(Boolean).join(" · ");
    $("#dLink").href = link(g);
    $("#dLink").textContent = isRawg(g) ? "Celé požadavky na RAWG →" : "Celé požadavky na Steamu →";

    const vbox = $("#dVerdict"); vbox.textContent = "";
    if (!knownReq(g)) {
      const b = el("div", "verdict-big unknown", unknownLabel(g));
      b.append(el("span", null, g.noReq ? "– RAWG u této hry požadavky neuvádí." : "– požadavky jsou níže v původním znění, porovnej si je sám."));
      vbox.append(b);
    } else if (v) {
      const b = el("div", "verdict-big " + v.overall, label(v));
      b.append(el("span", null, "– " + SUB[v.overall] + (v.partial ? " (část požadavků se nepodařilo přečíst)" : "")));
      vbox.append(b);
    } else vbox.append(el("p", "advice", "Vyplň nahoře svou sestavu a uvidíš, jestli tuhle hru rozjedeš."));

    const rows = $("#dRows"); rows.textContent = "";
    for (const k of ["cpu", "gpu", "ram"]) {
      const tr = el("tr");
      tr.append(el("th", null, KIND[k]));
      tr.append(el("td", v && v.parts[k] !== "unknown" ? v.parts[k] : null, k === "ram" ? (build.ram ? build.ram + " GB" : "–") : (build[k] ? build[k].name : "–")));
      const req = r => {
        const td = el("td");
        if (!r || r[k] == null) { td.textContent = g.reqText && k !== "ram" ? "nerozpoznáno" : "–"; if (g.reqText) td.className = "muted"; return td; }
        if (k === "ram") { td.textContent = gb(r.ram); return td; }
        const [first, ...rest] = r[k];
        td.append(first);
        if (rest.length) td.append(el("span", "alt", "nebo " + rest.join(", ")));
        return td;
      };
      tr.append(req(g.min), req(g.rec));
      rows.append(tr);
    }

    // advice: what's holding the PC back
    const adv = $("#dAdvice"); adv.textContent = "";
    if (v && (v.overall === "ok" || v.overall === "no")) {
      const target = v.overall === "no" ? g.min : g.rec;
      const weak = ["cpu", "gpu", "ram"].filter(k => (v.overall === "no" ? v.parts[k] === "no" : v.parts[k] === "ok") && target && target[k] != null);
      if (weak.length) {
        const p = el("p", "advice");
        p.append(el("strong", null, v.overall === "no" ? "Aby hra vůbec běžela, potřebuješ: " : "Pro doporučené nastavení potřebuješ: "));
        p.append(weak.map(k => k === "ram" ? `aspoň ${gb(target.ram)} paměti` :
          `${k === "cpu" ? "procesor" : "grafiku"} aspoň na úrovni ${target[k].slice(0, 2).join(" nebo ")}`).join("; ") + ".");
        adv.append(p);
      }
    }
    // the original requirement text, when part of it couldn't be read
    if (g.reqText && (g.reqText.min || g.reqText.rec)) {
      const box = el("details", "raw-req");
      box.open = !knownReq(g);
      box.append(el("summary", null, "Původní požadavky z RAWG"));
      if (g.reqText.min) box.append(el("p", null, g.reqText.min));
      if (g.reqText.rec) box.append(el("p", null, g.reqText.rec));
      adv.append(box);
    }
    dlg.showModal();
  }

  // ---------- Footer ----------
  $("#year").textContent = new Date().getFullYear();
  if (globalThis.GAMES_UPDATED) $("#updated").textContent = ` · aktualizováno ${fmtDate(globalThis.GAMES_UPDATED)}`;
  if (globalThis.GAMES_SOURCE !== "rawg") { $("#sourceLink").textContent = "Steam"; $("#sourceLink").href = "https://store.steampowered.com"; }

  render(true);
})();
